DigiBoardMap.install=()=>{
(()=>{
const R=PraatpadRoutes,W=1672,H=941;
const anchors=[[142, 840], [266, 779], [320, 735], [373, 696], [426, 658], [465, 610], [426, 567], [384, 523], [413, 481], [448, 441], [480, 400], [513, 362], [540, 330], [578, 307], [619, 335], [658, 366], [755, 422], [808, 442], [863, 461], [918, 483], [975, 504], [1107, 550], [1190, 550], [1271, 550], [1352, 550], [1432, 550], [1510, 549], [1496, 482], [1476, 423], [1458, 375], [1443, 329], [1430, 288], [1392, 247], [1344, 227], [1299, 206], [1251, 187], [1176, 157]];
const connections=[{"id": "kadetunnel", "type": "tunnel", "from": 5, "exits": [23], "label": "Haventunnel T1"}, {"id": "laadzone", "type": "extra_steps", "from": 29, "exits": [25], "delta": -4, "label": "Laadzone gesloten · vier vakken terug"}];
const fit=(w,h)=>{const scale=Math.min(w/W,h/H);return{scale,x:(w-W*scale)/2,y:(h-H*scale)/2}};
const legs=anchors.slice(0,-1).map((p,i)=>[p,anchors[i+1]]);
const map=(p,f)=>[p[0]*f.scale+f.x,p[1]*f.scale+f.y];
R.layout=(b,w,h)=>{const f=fit(w,h);return{points:anchors.map(p=>map(p,f)),tileWidth:64*f.scale,tileHeight:46*f.scale,pawnOffsetX:0,pawnOffsetY:0,scale:f.scale};};
R.coordinates=()=>anchors.map(([x,y])=>[x/W,y/H]);
R.routeGeometry=(b,w,h,c,to=c.exits[0])=>{const f=fit(w,h),points=(to===c.from+1?legs[c.from]:[anchors[c.from],anchors[to]]).map(p=>map(p,f));return{points,d:'M '+points.map(p=>p.join(' ')).join(' L '),from:points[0],to:points.at(-1),layout:R.layout(b,w,h),clear:true};};
R.mainPath=(b,w,h,stop=36)=>Array.from({length:stop},(_,i)=>R.routeGeometry(b,w,h,{from:i,exits:[i+1]}).d).join(' ');
R.artwork=()=>'';
R.portPosition=(b,w,h,c)=>R.layout(b,w,h).points[c.from];
function step(from,to,t,w,h){return{point:map(R.along(legs[from],Math.max(0,Math.min(1,t))),fit(w,h)),opacity:1,kind:from>=15&&from<=20?'bridge':'walk',boat:null};}
function pawnDepth(point,w,h){return 7;}
globalThis.PraatpadWorld={anchors,legs,fit,connections,step,pawnDepth,bridgeStart:15,boatMarkup:()=>'',departure:[0,0],arrival:[0,0],duration:()=>800};
globalThis.PraatpadCity={fit,anchors,angles:Array(37).fill(0)};
})();
// A scalable, colorable game piece; no embedded raster assets or font symbols.
PraatpadCity.pawn=(number='')=>`<svg viewBox="0 0 48 68" aria-hidden="true" focusable="false"><ellipse cx="24" cy="63" rx="21" ry="4" fill="#102e3a" opacity=".22"/><path d="M17 25C9 21 10 7 18 4C30-1 40 13 32 23L30 25C29 29 30 35 34 42L41 53C44 57 42 62 37 63H11C6 62 4 57 7 53L14 42C18 35 19 29 17 25Z" fill="currentColor" stroke="#fffdf4" stroke-width="3" stroke-linejoin="round"/><path d="M29 5C38 12 34 21 29 24C26 30 29 38 33 45L39 55C41 58 39 60 36 60H29C33 55 26 44 24 35C22 29 23 25 26 21C30 16 31 10 29 5Z" fill="#102e3a" opacity=".2"/><path d="M16 14C16 10 19 7 23 7" fill="none" stroke="#fff" stroke-opacity=".4" stroke-width="3" stroke-linecap="round"/><path d="M10 54C19 57 30 57 39 54" fill="none" stroke="#fff" stroke-opacity=".4" stroke-width="2"/><text x="24" y="48" fill="#fff" text-anchor="middle" font-family="Arial,sans-serif" font-size="17" font-weight="700">${number}</text></svg>`;
PraatpadCity.terminal=end=>`<span class="city-terminal-name">${end?'FINISH':'START'}</span><span class="city-terminal-sign" aria-hidden="true">${end?'<svg viewBox="0 0 40 32"><path d="M7 29V3" stroke="#163d4c" stroke-width="3"/><path d="M8 3H34V21H8Z" fill="#fff" stroke="#163d4c" stroke-width="2"/><path d="M8 3h7v6H8zm13 0h7v6h-7zm-6 6h6v6h-6zm13 0h6v6h-6zm-20 6h7v6H8zm13 0h7v6h-7z" fill="#163d4c"/></svg>':'<svg viewBox="0 0 40 32"><path d="M6 16H32M23 6L33 16L23 26" fill="none" stroke="#167562" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg>'}</span>`;


};
DigiBoardMap.positions={'kadetunnel':[835,689],'laadzone':[1320,387]};
DigiBoardMap.depthRoutes={tree:{from:27,exits:[30]},bridge:{from:15,exits:[21]}};
DigiBoardMap.connectRuntime=host=>{
const {$,root,Routes,s,current,routeConnections,reduced,drawMap,renderControls}=host;
function tunnelPose(t,from,to){return DigiBoardSpatial.pose('haven-kaderoute',t,from,to);}
globalThis.HavenTunnel={pose:tunnelPose,duration:6800,from:5,to:23};
function drawTunnelState(){
 const phase=host.anim?.tunnelPhase||'';root.dataset.tunnelPhase=phase;
 const trace=$('haven-underground');trace.style.visibility=phase==='hidden'?'visible':'hidden';
 if(phase==='hidden'){
  const k=host.anim.tunnelProgress||0,point=Routes.along(DigiBoardSpatial.trace('haven-kaderoute'),k);
  $('haven-underground-dot').setAttribute('cx',point[0]);$('haven-underground-dot').setAttribute('cy',point[1]);
 }
}
function animateTunnel(record,token){
 host.anim.pos=record.from;
 if(reduced()){host.anim.pos=record.to;drawMap();return Promise.resolve();}
 root.classList.add('pp-stepping');
 $('pp-transit-label').hidden=false;
 return new Promise(resolve=>{
  let start=null,raf=0,ended=false;
  const done=()=>{if(ended)return;ended=true;cancelAnimationFrame(raf);host.transportCancel=null;
   if(host.anim){delete host.anim.stepPoint;delete host.anim.cityTunnelOpacity;delete host.anim.tunnelScale;delete host.anim.tunnelPhase;delete host.anim.tunnelProgress;}
   root.classList.remove('pp-stepping');root.dataset.tunnelPhase='';$('haven-underground').style.visibility='hidden';$('pp-transit-label').hidden=true;resolve();
  };
  host.transportCancel=done;
  const frame=now=>{
   if(token!==host.run||!host.anim){done();return;}
   start??=now;const t=Math.min(1,(now-start)/6800),pose=tunnelPose(t,record.from,record.to),f=PraatpadWorld.fit($('pp-map').clientWidth,$('pp-map').clientHeight);
   host.anim.stepPoint=[pose.point[0]*f.scale+f.x,pose.point[1]*f.scale+f.y];
   host.anim.cityTunnelOpacity=pose.opacity;host.anim.tunnelScale=pose.scale;host.anim.tunnelPhase=pose.phase;host.anim.tunnelProgress=pose.progress;
   $('pp-transit-label').textContent=pose.phase==='hidden'?'T1 · Onder de grond → vak 23':pose.phase==='exit'||pose.phase==='arrive'?'T1 · De tunnel uit bij 23':'T1 · De haventunnel in bij 5';
   drawMap();
   host.previewLanding?.(t);if(t===1){host.anim.pos=record.to;done();drawMap();}else raf=requestAnimationFrame(frame);
  };raf=requestAnimationFrame(frame);
 });
}


function connectionRule(c){if(c.type==='tunnel')return `T1: land op vak ${c.from}. Loop de haventunnel in, ga onder de grond en kom bij vak ${c.exits[0]} weer boven. Doe daar de opdracht.`;if(c.type==='extra_steps')return `Land op vak ${c.from}: ga ${Math.abs(c.exits[0]-c.from)} ${c.exits[0]>c.from?'stappen vooruit':'stap'+(c.from-c.exits[0]===1?'':'pen')+' terug'} naar vak ${c.exits[0]}. Doe daar de opdracht.`;const t=Routes.getType(c.type);return `${c.enabled===false?'Gesloten. ':''}${c.optional?'Je mag ook op de ingang blijven. ':''}${t.rule==='history'?`Vanaf vak ${c.from}: kies een eerder eindvak van deze pion. Beurt en sleutels blijven staan.`:Routes.ruleText(c)}`;}
return{rule:connectionRule,draw(){drawTunnelState();},adjustPawn(el,w,h){},animate(record,token){const c=routeConnections().find(c=>c.id===record.id||c.from===record.from);if(c?.type==='tunnel')return animateTunnel(record,token);return null;}};
};
